23	// --------------------------------------------------------------------------------------------
24	// Atomics
25	// We need to be portable between C, C++, and MSVC.
26	// We base the primitives on the C/C++ atomics and create a minimal wrapper for MSVC in C compilation mode.
27	// This is why we try to use only `uintptr_t` and `<type>*` as atomic types.
28	// To gain better insight in the range of used atomics, we use explicitly named memory order operations
29	// instead of passing the memory order as a parameter.
30	// -----------------------------------------------------------------------------------------------
31	
32	#if defined(__cplusplus)
33	// Use C++ atomics
34	#include <atomic>
35	#define  _Atomic(tp)              std::atomic<tp>
36	#define  mi_atomic(name)          std::atomic_##name
37	#define  mi_memory_order(name)    std::memory_order_##name
