39	 #define MI_ATOMIC_VAR_INIT(x)    x
40	#elif !defined(ATOMIC_VAR_INIT)
41	 #define MI_ATOMIC_VAR_INIT(x)    x
42	#else
43	 #define MI_ATOMIC_VAR_INIT(x)    ATOMIC_VAR_INIT(x)
44	#endif
45	#elif defined(_MSC_VER)
46	// Use MSVC C wrapper for C11 atomics
