65	// Various defines for all used memory orders in mimalloc
66	#define mi_atomic_cas_weak(p,expected,desired,mem_success,mem_fail)  \
67	  mi_atomic(compare_exchange_weak_explicit)(p,expected,desired,mem_success,mem_fail)
68	
69	#define mi_atomic_cas_strong(p,expected,desired,mem_success,mem_fail)  \
70	  mi_atomic(compare_exchange_strong_explicit)(p,expected,desired,mem_success,mem_fail)
