135	// These are used by the statistics
136	static inline int64_t mi_atomic_addi64_relaxed(volatile int64_t* p, int64_t add) {
137	  return mi_atomic(fetch_add_explicit)((_Atomic(int64_t)*)p, add, mi_memory_order(relaxed));
138	}
139	static inline void mi_atomic_void_addi64_relaxed(volatile int64_t* p, const volatile int64_t* padd) {
140	  const int64_t add = mi_atomic_load_relaxed((_Atomic(int64_t)*)padd);
141	  if (add != 0) {
142	    mi_atomic(fetch_add_explicit)((_Atomic(int64_t)*)p, add, mi_memory_order(relaxed));
143	  }
144	}
145	static inline void mi_atomic_maxi64_relaxed(volatile int64_t* p, int64_t x) {
146	  int64_t current = mi_atomic_load_relaxed((_Atomic(int64_t)*)p);
147	  while (current < x && !mi_atomic_cas_weak_release((_Atomic(int64_t)*)p, &current, x)) { /* nothing */ };
148	}
