176	typedef enum mi_memory_order_e {
177	  mi_memory_order_relaxed,
178	  mi_memory_order_consume,
179	  mi_memory_order_acquire,
180	  mi_memory_order_release,
181	  mi_memory_order_acq_rel,
182	  mi_memory_order_seq_cst
183	} mi_memory_order;
