185	static inline uintptr_t mi_atomic_fetch_add_explicit(_Atomic(uintptr_t)*p, uintptr_t add, mi_memory_order mo) {
186	  (void)(mo);
187	  return (uintptr_t)MI_MSC_64(_InterlockedExchangeAdd)((volatile msc_intptr_t*)p, (msc_intptr_t)add);
188	}
189	static inline uintptr_t mi_atomic_fetch_sub_explicit(_Atomic(uintptr_t)*p, uintptr_t sub, mi_memory_order mo) {
190	  (void)(mo);
191	  return (uintptr_t)MI_MSC_64(_InterlockedExchangeAdd)((volatile msc_intptr_t*)p, -((msc_intptr_t)sub));
192	}
193	static inline uintptr_t mi_atomic_fetch_and_explicit(_Atomic(uintptr_t)*p, uintptr_t x, mi_memory_order mo) {
194	  (void)(mo);
195	  return (uintptr_t)MI_MSC_64(_InterlockedAnd)((volatile msc_intptr_t*)p, (msc_intptr_t)x);
196	}
197	static inline uintptr_t mi_atomic_fetch_or_explicit(_Atomic(uintptr_t)*p, uintptr_t x, mi_memory_order mo) {
198	  (void)(mo);
199	  return (uintptr_t)MI_MSC_64(_InterlockedOr)((volatile msc_intptr_t*)p, (msc_intptr_t)x);
200	}
201	static inline bool mi_atomic_compare_exchange_strong_explicit(_Atomic(uintptr_t)*p, uintptr_t* expected, uintptr_t desired, mi_memory_order mo1, mi_memory_order mo2) {
202	  (void)(mo1); (void)(mo2);
203	  const uintptr_t read = (uintptr_t)MI_MSC_64(_InterlockedCompareExchange)((volatile msc_intptr_t*)p, (msc_intptr_t)desired, (msc_intptr_t)(*expected));
204	  if (read == *expected) {
205	    return true;
206	  }
207	  else {
208	    *expected = read;
209	    return false;
210	  }
211	}
212	static inline bool mi_atomic_compare_exchange_weak_explicit(_Atomic(uintptr_t)*p, uintptr_t* expected, uintptr_t desired, mi_memory_order mo1, mi_memory_order mo2) {
213	  return mi_atomic_compare_exchange_strong_explicit(p, expected, desired, mo1, mo2);
214	}
215	static inline uintptr_t mi_atomic_exchange_explicit(_Atomic(uintptr_t)*p, uintptr_t exchange, mi_memory_order mo) {
216	  (void)(mo);
217	  return (uintptr_t)MI_MSC_64(_InterlockedExchange)((volatile msc_intptr_t*)p, (msc_intptr_t)exchange);
218	}
219	
220	static inline uintptr_t mi_atomic_load_explicit(_Atomic(uintptr_t) const* p, mi_memory_order mo) {
221	  (void)(mo);
222	  // assert(mo<=mi_memory_order_acquire); // others are not used by mimalloc
223	  #if defined(_M_IX86) || defined(_M_X64)
224	    // on x86/x64 we have a strong memory model so any load is acquire
225	    return (uintptr_t)MI_MSC_XX(__iso_volatile_load)((volatile const intptr_t*)p);
226	  #elif defined(_M_ARM) || defined(_M_ARM64)
227	    if (mo == mi_memory_order_relaxed) {
228	      return (uintptr_t)MI_MSC_XX(__iso_volatile_load)((volatile const intptr_t*)p);
229	    }
230	    else if (mo <= mi_memory_order_acquire) {
231	      return MI_MSC_XX(__ldar)((volatile const uintptr_t*)p);
232	    }
233	    else {
234	      const uintptr_t u = (uintptr_t)MI_MSC_XX(__iso_volatile_load)((volatile const intptr_t*)p);
235	      __dmb(15);  // _ARM(64)_BARRIER_SY
236	      return u;
237	    }
238	  #else
239	    #warning "define mi_atomic_load_explicit for MSVC C compilation on this platform (which should be readonly, see issue #1277)"
240	    return MI_MSC_XX(__iso_volatile_load)((volatile const intptr_t*)p);
241	  #endif
242	}
243	static inline void mi_atomic_store_explicit(_Atomic(uintptr_t)*p, uintptr_t x, mi_memory_order mo) {
244	  (void)(mo);
245	  // assert(mo<=mi_memory_order_release); // others are not used by mimalloc
246	  #if defined(_M_IX86) || defined(_M_X64)
247	    MI_MSC_XX(__iso_volatile_store)((volatile intptr_t*)p, x);
248	  #elif defined(_M_ARM) || defined(_M_ARM64)
249	    if (mo == mi_memory_order_relaxed) {
250	      MI_MSC_XX(__iso_volatile_store)((volatile intptr_t*)p, x);
251	    }
252	    else if (mo <= mi_memory_order_release) {
253	      MI_MSC_XX(__stlr)((volatile uintptr_t*)p,x);
254	    }
255	    else {
256	      mi_atomic_exchange_explicit(p, x, mo);
257	    }
258	  #else
259	    mi_atomic_exchange_explicit(p, x, mo);
260	  #endif
261	}
