263	static inline int64_t mi_atomic_loadi64_explicit(_Atomic(int64_t)*p, mi_memory_order mo) {
264	  (void)(mo);
265	  // assert(mo<=mi_memory_order_acquire); // others are not used by mimalloc
266	  #if defined(_M_IX86) || defined(_M_X64)
267	    return __iso_volatile_load64((volatile const int64_t*)p);
268	  #elif defined(_M_ARM) || defined(_M_ARM64)
269	    if (mo == mi_memory_order_relaxed) {
270	      return __iso_volatile_load64((volatile const int64_t*)p);
271	    }
272	    #if defined(_M_ARM64)
273	    else if (mo <= mi_memory_order_acquire) {
274	      return __ldar64((volatile const uintptr_t*)p);
275	    }
276	    #endif
277	    else {
278	      const int64_t i = __iso_volatile_load64((volatile const int64_t*)p);
279	      __dmb(15);  // _ARM(64)_BARRIER_SY
280	      return i;
281	    }
282	  #else
283	    #warning "define mi_atomic_loadi64_explicit for MSVC C compilation on this platform (which should be readonly, see issue #1277)"
284	    return __iso_volatile_load64((volatile const int64_t*)p);
285	  #endif
286	}
