288	static inline void mi_atomic_storei64_explicit(_Atomic(int64_t)*p, int64_t x, mi_memory_order mo) {
289	  (void)(mo);
290	  // assert(mo<=mi_memory_order_release); // others are not used by mimalloc
291	  #if defined(_M_IX86) || defined(_M_X64)
292	    __iso_volatile_store64((volatile int64_t*)p,x);
293	  #elif defined(_M_ARM) || defined(_M_ARM64)
294	    if (mo == mi_memory_order_relaxed) {
295	      __iso_volatile_store64((volatile int64_t*)p,x);
296	    }
297	    #if defined(_M_ARM64)
298	    else if (mo == mi_memory_order_release) {
299	      __stlr64((volatile uint64_t*)p, (uint64_t)x);
300	    }
301	    #endif
302	    else {
303	      InterlockedExchange64(p, x);
304	    }
305	  #else
306	    InterlockedExchange64(p, x);
307	  #endif
308	}
