310	// These are used by the statistics
311	static inline int64_t mi_atomic_addi64_relaxed(volatile _Atomic(int64_t)*p, int64_t add) {
312	  #ifdef _WIN64
313	    return (int64_t)mi_atomic_addi((int64_t*)p, add);
314	  #elif defined(_M_ARM)
315	    return _InterlockedExchangeAdd64(p, add);
316	  #else
317	    // x86
318	    int64_t current;
319	    int64_t sum;
320	    do {
321	      current = __iso_volatile_load64((volatile const int64_t*)p);
322	      sum = current + add;
323	    } while (_InterlockedCompareExchange64(p, sum, current) != current);
324	    return current;
325	  #endif
326	}
