328	static inline void mi_atomic_void_addi64_relaxed(volatile int64_t* p, const volatile int64_t* padd) {
329	  const int64_t add = *padd;
330	  if (add != 0) {
331	    mi_atomic_addi64_relaxed((volatile _Atomic(int64_t)*)p, add);
332	  }
333	}
