335	static inline void mi_atomic_maxi64_relaxed(volatile _Atomic(int64_t)* p, int64_t x) {
336	  int64_t current;
337	  do {
338	    current = *p;
339	  } while (current < x && _InterlockedCompareExchange64(p, x, current) != current);
340	}
