346	static inline bool mi_atomic_casi64_strong_acq_rel(volatile _Atomic(int64_t)* p, int64_t* exp, int64_t des) {
347	  const int64_t read = _InterlockedCompareExchange64(p, des, *exp);
348	  if (read == *exp) {
349	    return true;
350	  }
351	  else {
352	    *exp = read;
353	    return false;
354	  }
355	}
