379	// Atomically add a signed value; returns the previous value.
380	static inline intptr_t mi_atomic_addi(_Atomic(intptr_t)*p, intptr_t add) {
381	  return (intptr_t)mi_atomic_add_acq_rel((_Atomic(uintptr_t)*)p, (uintptr_t)add);
382	}
383	
384	// Atomically subtract a signed value; returns the previous value.
385	static inline intptr_t mi_atomic_subi(_Atomic(intptr_t)*p, intptr_t sub) {
386	  return (intptr_t)mi_atomic_addi(p, -sub);
387	}
388	
389	
390	// ----------------------------------------------------------------------
391	// Guard
392	// ----------------------------------------------------------------------
393	
394	typedef _Atomic(uintptr_t) mi_atomic_guard_t;
395	
396	// Allows only one thread to execute at a time (without blocking anyone)
397	#define mi_atomic_guard(guard) \
398	  uintptr_t _mi_guard_expected = 0; \
399	  for(bool _mi_guard_once = true; \
400	      _mi_guard_once && mi_atomic_cas_strong_acq_rel(guard,&_mi_guard_expected,(uintptr_t)1); \
401	      (mi_atomic_store_release(guard,(uintptr_t)0), _mi_guard_once = false) )
402	
403	
404	// ----------------------------------------------------------------------
405	// Locks
406	// These should be light-weight in-process only locks.
407	// Only used for reserving arena's and to maintain the abandoned list.
408	// ----------------------------------------------------------------------
409	#if _MSC_VER
410	#pragma warning(disable:26110)  // unlock with holding lock
411	#endif
412	
413	#define mi_lock(lock)                  for(bool _mi_go = (mi_lock_acquire(lock),true); _mi_go; (mi_lock_release(lock), _mi_go=false) )
414	#define mi_lock_maybe(lock,acquire)    for(bool _mi_go = (acquire ? (mi_lock_acquire(lock),true) : true); _mi_go; _mi_go = (acquire ? (mi_lock_release(lock),false) : false) )
415	
416	
417	#if defined(_WIN32) || defined(__CYGWIN__)
418	
419	typedef struct mi_lock_s {
420	  SRWLOCK mutex;    // slim reader-writer lock
421	} mi_lock_t;
422	
423	#define MI_LOCK_INITIALIZER   { SRWLOCK_INIT }
424	
425	static inline bool mi_lock_try_acquire(mi_lock_t* lock) {
426	  return TryAcquireSRWLockExclusive(&lock->mutex);
427	}
428	static inline void mi_lock_acquire(mi_lock_t* lock) {
429	  AcquireSRWLockExclusive(&lock->mutex);
430	}
431	static inline void mi_lock_release(mi_lock_t* lock) {
432	  ReleaseSRWLockExclusive(&lock->mutex);
433	}
434	static inline void mi_lock_init(mi_lock_t* lock) {
435	  InitializeSRWLock(&lock->mutex);
436	}
437	static inline void mi_lock_done(mi_lock_t* lock) {
438	  (void)(lock);
439	}
440	
441	#elif defined(MI_USE_PTHREADS)
442	
443	#include <string.h> // memcpy
444	void _mi_error_message(int err, const char* fmt, ...);
445	
446	typedef struct mi_lock_s {
447	  pthread_mutex_t mutex;
448	} mi_lock_t;
449	
450	#define MI_LOCK_INITIALIZER { PTHREAD_MUTEX_INITIALIZER }
451	
452	static inline bool mi_lock_try_acquire(mi_lock_t* lock) {
453	  return (pthread_mutex_trylock(&lock->mutex) == 0);
454	}
455	static inline void mi_lock_acquire(mi_lock_t* lock) {
456	  const int err = pthread_mutex_lock(&lock->mutex);
457	  if (err != 0) {
458	    _mi_error_message(err, "internal error: lock cannot be acquired (err %i)\n", err);
459	  }
460	}
461	static inline void mi_lock_release(mi_lock_t* lock) {
462	  pthread_mutex_unlock(&lock->mutex);
463	}
464	static inline void mi_lock_init(mi_lock_t* lock) {
465	  if(lock==NULL) return;
466	  // use this instead of pthread_mutex_init since that can cause allocation on some platforms (and recursively initialize)
467	  const pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
468	  memcpy(&lock->mutex,&mutex,sizeof(mutex));
469	}
470	static inline void mi_lock_done(mi_lock_t* lock) {
471	  pthread_mutex_destroy(&lock->mutex);
472	}
473	
474	#elif defined(__cplusplus)
475	
476	#include <thread>
477	#include <mutex>
478	#include <new>
479	
480	typedef struct mi_lock_s {
481	  std::mutex mutex;
482	} mi_lock_t;
483	
484	#define MI_LOCK_INITIALIZER   { }
485	
486	static inline bool mi_lock_try_acquire(mi_lock_t* lock) {
487	  return lock->mutex.try_lock();
488	}
489	static inline void mi_lock_acquire(mi_lock_t* lock) {
490	  lock->mutex.lock();
491	}
492	static inline void mi_lock_release(mi_lock_t* lock) {
493	  lock->mutex.unlock();
494	}
495	static inline void mi_lock_init(mi_lock_t* lock) {
496	  new(&lock->mutex) std::mutex();  // in-place constructor
497	}
498	static inline void mi_lock_done(mi_lock_t* lock) {
499	  lock->mutex.~mutex(); // in-place destructor
500	}
501	
502	#else
503	
504	// fall back to poor man's locks.
505	// this should only be the case in a single-threaded environment (like __wasi__)
506	#include <errno.h>
507	#ifndef EFAULT
508	#define EFAULT (14)
509	#endif
510	void _mi_error_message(int err, const char* fmt, ...);
511	void _mi_prim_thread_yield(void);
512	
513	typedef struct mi_lock_s {
514	  _Atomic(uintptr_t) mutex;
515	} mi_lock_t;
516	
517	#define MI_LOCK_INITIALIZER  { MI_ATOMIC_VAR_INIT(0) }
518	
519	static inline bool mi_lock_try_acquire(mi_lock_t* lock) {
520	  uintptr_t expected = 0;
521	  return mi_atomic_cas_strong_acq_rel(&lock->mutex, &expected, (uintptr_t)1);
522	}
523	static inline void mi_lock_acquire(mi_lock_t* lock) {
524	  size_t ticks = 0;
525	  for (int i = 0; i < 10000; i++) {  // for at most 10000 tries?
526	    if (mi_lock_try_acquire(lock)) return;
527	    _mi_prim_thread_yield();
528	  }
529	  _mi_error_message(EFAULT, "internal error: lock cannot be acquired (due to lack of native lock primitives)\n");
530	}
531	static inline void mi_lock_release(mi_lock_t* lock) {
532	  mi_atomic_store_release(&lock->mutex, (uintptr_t)0);
533	}
534	static inline void mi_lock_init(mi_lock_t* lock) {
535	  mi_lock_release(lock);
536	}
537	static inline void mi_lock_done(mi_lock_t* lock) {
538	  (void)(lock);
539	}
540	
541	#endif
542	
543	
544	typedef struct mi_atomic_once_s {
545	  _Atomic(uintptr_t) tid;
546	  mi_lock_t          lock;
547	} mi_atomic_once_t;
548	
549	// Returns `true` only on the first invocation, signifying we can execute an action once.
550	// If it returns `true`, the caller should call `_mi_atomic_once_release` after performing the action.
551	// Other threads (than the initial thread that entered) will block until `_mi_atomic_once_release` has been called.
552	bool _mi_atomic_once_enter(mi_atomic_once_t* once);        // defined in `libc.c`
553	void _mi_atomic_once_release(mi_atomic_once_t* once);      // defined in `libc.c`
554	
555	#define mi_atomic_do_once  \
556	  static mi_atomic_once_t _mi_once = { MI_ATOMIC_VAR_INIT(0), MI_LOCK_INITIALIZER }; \
557	  for(bool _mi_exec = _mi_atomic_once_enter(&_mi_once); _mi_exec; (_mi_atomic_once_release(&_mi_once),_mi_exec=false))
558	
559	
560	#endif // __MIMALLOC_ATOMIC_H
