436	    mi_assert_internal(sub!=NULL);
437	    // set the offsets for the page
438	    while (slice_count > 0 && sub_idx < MI_PAGE_MAP_SUB_COUNT) {
439	      sub[sub_idx] = page;
440	      slice_count--;
441	      sub_idx++;
442	    }
443	    idx++; // potentially wrap around to the next idx
444	    sub_idx = 0;
445	  }
446	  return true;
447	}
